use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let s = input.as_str().unwrap();
    let mut result = String::new();
    let mut chars = s.chars().peekable();

    while let Some(c) = chars.next() {
        if c.is_alphanumeric() {
            result.push(c);
        } else {
            if !result.is_empty() {
                result.push('-');
            }
            result.push(c);
        }
    }

    Value::String(result)
}
